(x, y, t) => {
  const attractors = [
    [160+Math.sin(t*0.4)*120, 80+Math.cos(t*0.3)*60, 3.0],
    [320+Math.cos(t*0.35)*100, 160+Math.sin(t*0.5)*70, 2.5],
    [240+Math.sin(t*0.25+2)*140, 120+Math.cos(t*0.4+1)*80, 3.5],
    [80+Math.cos(t*0.6+1)*60, 200+Math.sin(t*0.45+3)*50, 2.0],
    [400+Math.sin(t*0.3+4)*70, 40+Math.cos(t*0.7+2)*50, 2.8],
    [240+Math.cos(t*0.3+5)*100, 220+Math.sin(t*0.4)*60, 2.2]
  ];
  let potE = 0, kinE = 0, flowX = 0, flowY = 0;
  for (const [ax, ay, mass] of attractors) {
    const dx = x - ax, dy = y - ay;
    const dist = Math.sqrt(dx*dx + dy*dy) + 1;
    const force = mass / (dist * 0.1 + 1);
    potE += force * 0.3;
    flowX += (dx / dist) * force;
    flowY += (dy / dist) * force;
    kinE += force * 0.2 / (dist * 0.01 + 1);
  }
  const transform = Math.sin(potE * 0.5 - kinE * 0.8 + t * 0.6);
  const wx = Math.sin(flowX*0.05+t*0.2)*22 + Math.cos(flowY*0.04-t*0.15)*16;
  const wy = Math.cos(flowY*0.05-t*0.18)*22 + Math.sin(flowX*0.04+t*0.25)*16;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9]
  ];
  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) + Math.sin(d*f*1.7 - t*sp*1.3 + 0.8)*0.5;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) + Math.cos(d*f*1.2 + t*sp*0.4)*0.4;
  }
  const act = aS/9, inh = iS/8.4;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + transform*0.3;
  const cx = 240, cy = 120;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const eC = transform*0.3+Math.sin((potE+kinE)*0.2+t)*0.2;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+eC)*2.5);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const detail = Math.sin(sx*0.3+Math.sin(sy*0.2+t)*2)*Math.sin(sy*0.25+Math.cos(sx*0.15-t)*2)*0.15;
  const blend = reaction*0.65+cell*0.2+detail*0.15, v = blend*0.5+0.5;
  const pal = [[2,2,15],[8,15,70],[0,240,190],[160,255,40],[255,40,140],[190,0,255],[255,160,0],[255,255,255],[2,2,15]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.9+Math.sin(reaction*Math.PI)*0.3+Math.abs(transform)*0.15;
  const edge = Math.abs(reaction)>0.6?1.35:(Math.abs(reaction)<0.1?0.35:1.0);
  const glow = Math.max(0,reaction)**2*0.5;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*70)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*110)|0)
  ];
}
